<script setup lang="ts">
import {computed,ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import {useI18n} from 'vue-i18n';import {api} from '@/api';import {idempotencyKey} from '@shared/net/http-client';import {currentCurrency,money} from '@shared/utils/money';import {isoDate} from '@shared/utils/datetime';import {fixedMinor} from '@/shared/stored-value-form';import {definiteGovernanceRejection} from '@/shared/stored-value-governance-errors';import type {SvActivity,SvActivityDefinition,SvSubmission,SvGovernanceContext} from '@/api/stored-value-governance';
const {t}=useI18n();const m=ref(''),store=ref(''),activity=ref<SvActivity|null>(null),submission=ref<SvSubmission|null>(null),context=ref<SvGovernanceContext|null>(null),loading=ref(true),failed=ref(false),busy=ref(false),error=ref('');
const name=ref(''),start=ref(isoDate(Date.now())),end=ref(isoDate(Date.now()+29*86400000)),tiers=ref([{no:idempotencyKey(),paid:'',bonus:'0'}]),templates=ref<Array<{templateCode:string;templateVersion:number;name:string}>>([]),template=ref(''),choosing=ref(false);
type Pending={kind:'SAVE';no:string|null;definition:SvActivityDefinition;revision?:number;key:string;submit:boolean}|{kind:'SUBMIT'|'STOP'|'COPY';no:string;revision:number;key:string;definition:SvActivityDefinition};
const pending=ref<Pending|null>(null);const storage=computed(()=>`sv-activity-pending:${m.value}:${store.value}`);const locked=computed(()=>!context.value?.canManage||busy.value||!!pending.value||!!activity.value&&activity.value.status!=='DRAFT');
function restore(d:SvActivityDefinition){name.value=d.name;template.value=d.templateCode;tiers.value=d.rule.tiers.map(x=>({no:x.tierNo,paid:String(x.payAmountMinor/10**context.value!.currencyScale),bonus:String(x.bonusAmountMinor/10**context.value!.currencyScale)}));start.value=isoDate(Date.parse(d.schedule.startAt));end.value=isoDate(Date.parse(d.schedule.endAt)-1)}
async function load(no?:string){loading.value=true;failed.value=false;try{context.value=await api.mSvActivityContext(store.value,{managementNo:m.value,currency:currentCurrency(),intent:'READ'});if(context.value.canManage){const p=await api.mSvActivityPresets(store.value,{managementNo:m.value,currency:context.value.currency,size:50});templates.value=p.records.filter(x=>x.enabled&&x.available);template.value=templates.value[0]?.templateCode||'';}if(no){const result=await api.mSvActivity(store.value,no,{managementNo:m.value,currency:context.value.currency});activity.value=result.activity;submission.value=result.submission;restore(result.activity.definition)}const saved=uni.getStorageSync(storage.value);if(saved){pending.value=JSON.parse(String(saved)) as Pending;restore(pending.value.definition)}}catch(e){failed.value=true;error.value=(e as Error).message}finally{loading.value=false}}
async function definition():Promise<SvActivityDefinition>{if(!context.value||!name.value.trim()||!tiers.value.length)throw Error(t('svGov.invalidActivity'));const preset=templates.value.find(x=>x.templateCode===template.value);if(!preset)throw Error(t('svGov.noTemplates'));const schedule=await api.mSvActivitySchedule(store.value,{managementNo:m.value,currency:context.value.currency,startDate:start.value,endDate:end.value});return{name:name.value.trim(),scene:'RECHARGE',templateCode:preset.templateCode,templateVersion:preset.templateVersion,storeParticipationScope:{mode:'STORES',refs:[store.value]},audienceRef:null,schedule:{type:'ONE_OFF',startAt:schedule.startAt,endAt:schedule.endAt,zone:schedule.zone,weekdays:[],from:null,to:null},rule:{schemaVersion:1,trigger:{type:'NONE',amountMinor:null,quantity:null},benefits:[],tiers:tiers.value.map(x=>({tierNo:x.no,payAmountMinor:fixedMinor(x.paid,context.value!.currencyScale),bonusAmountMinor:fixedMinor(x.bonus,context.value!.currencyScale),redemptionScope:{mode:'STORES',refs:[store.value]}}))},quotaLimit:null,budgetLimitMinor:null,perUserLimit:2147483647,currency:context.value.currency}}
function persist(p:Pending){uni.setStorageSync(storage.value,JSON.stringify(p));pending.value=p}
async function copy(){if(busy.value||!context.value?.canManage||!activity.value||pending.value)return;persist({kind:'COPY',no:activity.value.activityNo,revision:activity.value.revision,key:idempotencyKey(),definition:activity.value.definition});await execute();}
async function execute(submit=false,stop=false){if(busy.value||!context.value?.canManage||submit&&!context.value.canPublish)return;error.value='';busy.value=true;try{if(!pending.value){if(stop){if(!activity.value||!submission.value)throw Error(t('svGov.invalidActivity'));persist({kind:'STOP',no:activity.value.activityNo,revision:Number(submission.value.draftRevisionNo),key:idempotencyKey(),definition:activity.value.definition})}else if(activity.value?.status!=='DRAFT'&&activity.value){throw Error(t('svGov.invalidActivity'))}else{const d=await definition();persist({kind:'SAVE',no:activity.value?.activityNo||null,revision:activity.value?.revision,definition:d,key:idempotencyKey(),submit})}}
 let p=pending.value!;
 if(p.kind==='SAVE'){const result=await api.mSvActivitySave(store.value,p.no,{managementNo:m.value,definition:p.definition,expectedRevision:p.revision},p.key);activity.value=result;if(p.submit){const check=await api.mSvActivityCheck(store.value,result.activityNo,{managementNo:m.value,currency:result.definition.currency,expectedRevision:result.revision});if(!check.allowed){uni.removeStorageSync(storage.value);pending.value=null;throw Error(t('svGov.invalidRules'));}persist({kind:'SUBMIT',no:result.activityNo,revision:result.revision,key:idempotencyKey(),definition:result.definition});p=pending.value!}else{uni.removeStorageSync(storage.value);pending.value=null;uni.showToast({title:t('svGov.saved'),icon:'none'});return}}
 if(p.kind==='COPY'){const copied=await api.mSvActivityCopy(store.value,p.no,{managementNo:m.value,currency:p.definition.currency,expectedRevision:p.revision},p.key);uni.removeStorageSync(storage.value);pending.value=null;uni.redirectTo({url:'/pages/stored-value-activity-edit/index?m='+encodeURIComponent(m.value)+'&s='+encodeURIComponent(store.value)+'&a='+encodeURIComponent(copied.activityNo)});return}
 if(p.kind==='SUBMIT'||p.kind==='STOP'){const command={managementNo:m.value,currency:p.definition.currency,expectedRevision:p.revision};submission.value=await(p.kind==='SUBMIT'?api.mSvActivitySubmit(store.value,p.no,command,p.key):api.mSvActivityStop(store.value,p.no,command,p.key));uni.removeStorageSync(storage.value);pending.value=null;await load(p.no)}
 }catch(e){error.value=(e as Error).message;await reconcilePending(e);}finally{busy.value=false}}
async function reconcilePending(error:unknown){
 const p=pending.value;if(!p||!['SUBMIT','STOP'].includes(p.kind))return;
 try{const actual=await api.mSvActivity(store.value,p.no!,{managementNo:m.value,currency:p.definition.currency});const state=actual.submission;const same=state?.draftRevisionNo===String(p.revision);const terminal=same&&(p.kind==='STOP'?state?.state==='STOPPED':['ACTIVE','PENDING_APPROVAL','STALE','BLOCKED_POLICY','STOPPED'].includes(state!.state));
 if(terminal||p.kind==='SUBMIT'&&definiteGovernanceRejection(error)&&!state){uni.removeStorageSync(storage.value);pending.value=null;activity.value=actual.activity;submission.value=state;restore(actual.activity.definition);}
 }catch{/* Preserve original command until its durable outcome is known. */}
}
onLoad(q=>{m.value=q?.m||'';store.value=q?.s||'';void load(q?.a)});
</script>
<template><sh-scaffold title-key="svGov.activityDetail" :pending="loading" :failed="failed" @retry="load(activity?.activityNo)">
 <view v-if="submission" class="sh-card"><text class="txt-title">{{t(`svGov.states.${submission.state}`)}}</text></view>
 <template v-if="context"><view class="sh-card"><view class="field"><text class="field__label">{{t('svGov.name')}}</text><input data-testid="activity-name" v-model="name" class="field__input" maxlength="100" :disabled="locked"/></view><view class="sh-cell sh-row sh-row--between" @tap="!locked&&(choosing=true)"><text>{{t('svGov.template')}}</text><text>{{templates.find(x=>x.templateCode===template)?.name||t('svGov.chooseTemplate')}}</text><sh-go/></view><view class="sh-cell"><text>{{t('svGov.startDate')}}</text><picker mode="date" :value="start" :disabled="locked" @change="start=$event.detail.value"><text>{{start}}</text></picker></view><view class="sh-cell"><text>{{t('svGov.endDate')}}</text><picker mode="date" :value="end" :disabled="locked" @change="end=$event.detail.value"><text>{{end}}</text></picker></view></view>
 <view v-for="(tier,i) in tiers" :key="tier.no" class="sh-card"><view class="sh-row sh-row--between"><text class="txt-title">{{t('svGov.tier')}} {{i+1}}</text><text v-if="tiers.length>1&&!locked" class="sh-link" @tap="tiers.splice(i,1)">{{t('svGov.remove')}}</text></view><view class="field"><text class="field__label">{{t('svGov.paid')}} · {{context.currency}}</text><input maxlength="10" data-testid="tier-paid" v-model="tier.paid" type="digit" class="field__input" :disabled="locked"/></view><view class="field"><text class="field__label">{{t('svGov.bonus')}} · {{context.currency}}</text><input maxlength="10" data-testid="tier-bonus" v-model="tier.bonus" type="digit" class="field__input" :disabled="locked"/></view></view>
 <view data-testid="add-tier" v-if="!locked&&tiers.length<50" class="sh-btn sh-btn--soft" @tap="tiers.push({no:idempotencyKey(),paid:'',bonus:'0'})">{{t('svGov.addTier')}}</view>
 <text v-if="pending" class="sh-hint">{{t('svGov.unknown')}}</text><text v-if="error" class="sh-hint">{{error}}</text>
 <sh-actionbar v-if="context.canManage"><view data-testid="activity-retry" v-if="pending" class="sh-btn" :class="{'is-disabled':busy}" @tap="execute()">{{t('svGov.retry')}}</view><view v-else-if="!activity||activity.status==='DRAFT'" class="sh-row"><view class="sh-btn sh-btn--soft sh-fill" :class="{'is-disabled':busy}" @tap="execute(false)">{{t('svGov.saveDraft')}}</view><view data-testid="activity-submit" v-if="context.canPublish" class="sh-btn sh-fill" :class="{'is-disabled':busy}" @tap="execute(true)">{{t('svGov.submit')}}</view></view><view v-else class="sh-row"><view data-testid="activity-copy" class="sh-btn sh-btn--soft sh-fill" :class="{'is-disabled':busy}" @tap="copy">{{t('svGov.copy')}}</view><view v-if="submission?.state==='ACTIVE'" class="sh-btn sh-btn--soft" :class="{'is-disabled':busy}" @tap="execute(false,true)">{{t('svGov.stop')}}</view></view></sh-actionbar>
 <sh-sheet :visible="choosing" :title="t('svGov.chooseTemplate')" @close="choosing=false"><view v-for="x in templates" :key="x.templateCode" class="sh-cell sh-row sh-row--between" @tap="template=x.templateCode;choosing=false"><text>{{x.name}}</text><sh-check :model-value="template===x.templateCode" round/></view><sh-empty :pending="loading" v-if="!templates.length" :text="t('svGov.noTemplates')"/></sh-sheet>
 </template></sh-scaffold></template>
